script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.technique.id', 'T1210');
        v.get('_source').put('threat.technique.name', 'Exploitation of Remote Services');
        v.get('_source').put('threat.technique.reference', 'https://attack.mitre.org/techniques/T1210');
        v.get('_source').put('threat.tactic.id', 'TA0008, TA0005');
        v.get('_source').put('threat.tactic.name', 'Lateral Movement, Defense Evasion');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0008, https://attack.mitre.org/tactics/TA0005');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'AWS Guardduty Unauthorised Access Alert');
        v.get('_source').put('threat.detection_description', 'AWS Guardduty detects alerts when someone gains access to a website, program, server, service, or other system using someone an account belonging to someone else or other methods.');
        v.get('_source').put('threat.severity', 'medium');
        v.get('_source').put('threat.triage_score', 40);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
